		private Color ColorFromProportion(float proportion)
		{
			proportion = Math.Max(0f, Math.Min(1f, proportion));
			Color[] array = new Color[]
			{
				Color.Blue,
				Color.Cyan,
				Color.FromArgb(0, 255, 0),
				Color.Yellow,
				Color.Red
			};
