			int num2 = (int)(proportion / num);
			int num3 = Math.Min(num2 + 1, array.Length - 1);
			float num4 = (proportion - (float)num2 * num) / num;
			Color color = array[num2];
			Color color2 = array[num3];
			int red = (int)((float)color.R * (1f - num4) + (float)color2.R * num4);
			int green = (int)((float)color.G * (1f - num4) + (float)color2.G * num4);
			int blue = (int)((float)color.B * (1f - num4) + (float)color2.B * num4);
			return Color.FromArgb(red, green, blue);
		}

