		private int FindClosestIndex(List<double> values, double target)
		{
			int result = 0;
			double num = Math.Abs(values[0] - target);
			for (int i = 1; i < values.Count; i++)
			{
				double num2 = Math.Abs(values[i] - target);
				bool flag = num2 < num;
				if (flag)
				{
					num = num2;
					result = i;
				}
			}
			return result;
		}

